import React, { useState } from 'react';
import { ArrowUp, ArrowDown, Pencil, Trash2, Check, X, Plus } from 'lucide-react';
import styles from './DynamicDataTable.module.css';
import { useDynamicDataMutations, useDataEntities } from '../../hooks/useDynamicData';
import { Button } from '../ui/Button';
import { useAuth } from '../../context/AuthContext';
import { Table, Thead, Tbody, Tr, Th, Td } from '../ui/Table';
import { Input } from '../ui/form/Input';
import { useModal } from '../../context/ModalContext';
import { Checkbox } from '../ui/form/Checkbox';
import { RadioGroup } from '../ui/form/RadioGroup';
import Pagination from '../ui/Pagination';

/**
 * DynamicDataTable: A reusable component to render and manage data for a specific DataType.
 * Handles CRUD operations and reordering.
 * @param {object} props.type - The DataType configuration object.
 */
const DynamicDataTable = ({ type }) => {
    const [currentPage, setCurrentPage] = useState(1);
    const limit = 10;
    const { data: response, loading, refresh } = useDataEntities(type._id, currentPage, limit);
    const { confirm } = useModal();

    // Normalize data based on whether it's paginated or not
    const entities = response?.data || (Array.isArray(response) ? response : []);
    const totalPages = response?.totalPages || 1;
    const { create, update, delete: del, reorder } = useDynamicDataMutations(type._id);

    const [isAdding, setIsAdding] = useState(false);
    const [editingId, setEditingId] = useState(null);
    const [formData, setFormData] = useState({});

    // Field names for table headers
    const headers = type.fields.map(f => f.name);

    /**
     * handleEdit: Enter editing mode for a specific record.
     */
    const handleEdit = (entity) => {
        setEditingId(entity._id);
        setFormData(entity);
    };

    /**
     * handleCancel: Exit editing/adding mode and reset state.
     */
    const handleCancel = () => {
        setEditingId(null);
        setIsAdding(false);
        setFormData({});
    };

    /**
     * handleSave: Create or Update a record based on current mode.
     */
    const handleSave = async (e) => {
        e.preventDefault();
        let res;
        if (isAdding) {
            res = await create(formData);
        } else {
            res = await update(editingId, formData);
        }

        if (res.success) {
            handleCancel();
            refresh();
        } else {
            alert(`Error saving: ${res.error?.message || 'Operation failed'}`);
        }
    };

    /**
     * handleDelete: Confirm and delete a record.
     */
    const handleDelete = async (id) => {
        const confirmed = await confirm({
            title: 'Delete Record',
            message: 'Are you sure you want to delete this record?',
            confirmText: 'Delete',
            intent: 'danger'
        });
        if (confirmed) {
            const res = await del(id);
            if (res.success) {
                refresh();
            } else {
                alert(`Error deleting: ${res.error?.message || 'Delete failed'}`);
            }
        }
    };

    /**
     * handleMove: Reorder records within the list.
     * @param {number} index - Current index of the item.
     * @param {number} direction - -1 for Up, 1 for Down.
     */
    const handleMove = async (index, direction) => {
        if (!entities) return;
        const newEntities = [...entities];
        const targetIndex = index + direction;

        if (targetIndex < 0 || targetIndex >= newEntities.length) return;

        // Swap items in local array
        const [movedItem] = newEntities.splice(index, 1);
        newEntities.splice(targetIndex, 0, movedItem);

        // Map to bulk update objects for backend: [{ id: string, order: number }, ...]
        const updates = newEntities.map((item, idx) => ({
            id: item._id,
            order: idx
        }));

        const res = await reorder(updates);
        if (res.success) {
            refresh();
        } else {
            alert(`Error reordering: ${res.error?.message || 'Operation failed'}`);
        }
    };

    /**
     * renderInput: Helper to render appropriate input field based on schema type.
     */
    /**
     * renderInput: Helper to render appropriate input field based on schema type.
     * Includes demo logic for Checkbox and Radio buttons.
     */
    const renderInput = (field, value, onChange, index = 0) => {
        const id = `field-${field.name}-${index}`;
        switch (field.type) {
            case 'boolean':
                return (
                    <Checkbox
                        id={id}
                        checked={!!value}
                        onChange={(e) => onChange(e.target.checked)}
                    />
                );
            case 'radio':
                // Fields with options like ['red', 'blue', 'green']
                const options = field.options || [];
                // Normalize options to {label, value} format if they are strings
                const radioOptions = options.map(opt =>
                    typeof opt === 'object' ? opt : { label: opt.charAt(0).toUpperCase() + opt.slice(1), value: opt }
                );

                return (
                    <RadioGroup
                        name={`${id}-group`}
                        direction="row"
                        value={value}
                        onChange={onChange}
                        options={radioOptions}
                    />
                );
            case 'number':
                return (
                    <Input
                        id={id}
                        type="number"
                        value={value ?? ''}
                        onChange={(e) => onChange(Number(e.target.value))}
                        required={field.required}
                    />
                );
            case 'date':
                return (
                    <Input
                        id={id}
                        type="date"
                        value={value ?? ''}
                        onChange={(e) => onChange(e.target.value)}
                        required={field.required}
                    />
                );
            default: // text
                return (
                    <Input
                        id={id}
                        type="text"
                        value={value ?? ''}
                        onChange={(e) => onChange(e.target.value)}
                        required={field.required}
                        placeholder={field.description}
                    />
                );
        }
    };

    if (loading && entities.length === 0) return <div className={styles.loading}>Loading data...</div>;

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <h2>{type.name}</h2>
                <p>{type.description}</p>
                {type.permissions.canAdd && (
                    <Button
                        onClick={() => { setIsAdding(true); setFormData({}); }}
                        disabled={isAdding || !!editingId}
                    >
                        <Plus size={16} />
                        <span>Add Record</span>
                    </Button>
                )}
            </div>

            <div className={styles.tableWrapper}>
                <Table dense={true}>
                    <Thead>
                        <Tr>
                            {type.isOrdered && <Th>Order</Th>}
                            {headers.map(h => <Th key={h}>{h}</Th>)}
                            <Th>Actions</Th>
                        </Tr>
                    </Thead>
                    <Tbody>
                        {/* Adding Row */}
                        {isAdding && (
                            <Tr className={styles.editRow}>
                                {type.isOrdered && <Td>-</Td>}
                                {type.fields.map(field => (
                                    <Td key={field.name}>
                                        {renderInput(field, formData[field.name], (val) => setFormData({ ...formData, [field.name]: val }), 999)}
                                    </Td>
                                ))}
                                <Td>
                                    <div className={styles.actions}>
                                        <Button onClick={handleSave} intent="success" variant="outline" size="sm" title="Save" grouped>
                                            <Check size={16} />
                                        </Button>
                                        <Button onClick={handleCancel} variant="outline" size="sm" title="Cancel" grouped>
                                            <X size={16} />
                                        </Button>
                                    </div>
                                </Td>
                            </Tr>
                        )}

                        {/* Data Rows */}
                        {entities?.map((entity, idx) => (
                            <Tr key={entity._id}>
                                {type.isOrdered && (
                                    <Td>
                                        <div className={styles.orderCell}>
                                            {type.permissions.canReorder && (
                                                <>
                                                    <Button onClick={() => handleMove(idx, -1)} disabled={idx === 0} variant="outline" size="sm" grouped>
                                                        <ArrowUp size={14} />
                                                    </Button>
                                                    <Button onClick={() => handleMove(idx, 1)} disabled={idx === entities.length - 1} variant="outline" size="sm" grouped>
                                                        <ArrowDown size={14} />
                                                    </Button>
                                                </>
                                            )}
                                            <span>{idx + 1}</span>
                                        </div>
                                    </Td>
                                )}
                                {type.fields.map(field => (
                                    <Td key={field.name}>
                                        {editingId === entity._id ? (
                                            renderInput(field, formData[field.name], (val) => setFormData({ ...formData, [field.name]: val }), idx)
                                        ) : (
                                            field.type === 'boolean' ? (entity[field.name] ? 'Yes' : 'No') : String(entity[field.name] ?? '')
                                        )}
                                    </Td>
                                ))}
                                <Td className={styles.actionsCell}>
                                    <div className={styles.actions}>
                                        {editingId === entity._id ? (
                                            <>
                                                <Button onClick={handleSave} intent="success" variant="outline" size="sm" title="Save" grouped>
                                                    <Check size={16} />
                                                </Button>
                                                <Button onClick={handleCancel} variant="outline" size="sm" title="Cancel" grouped>
                                                    <X size={16} />
                                                </Button>
                                            </>
                                        ) : (
                                            <>
                                                {type.permissions.canEdit && (
                                                    <Button onClick={() => handleEdit(entity)} size="sm" variant="outline" title="Edit" grouped>
                                                        <Pencil size={16} />
                                                    </Button>
                                                )}
                                                {type.permissions.canDelete && (
                                                    <Button onClick={() => handleDelete(entity._id)} intent="danger" size="sm" variant="outline" title="Delete" grouped>
                                                        <Trash2 size={16} />
                                                    </Button>
                                                )}
                                            </>
                                        )}
                                    </div>
                                </Td>
                            </Tr>
                        ))}
                    </Tbody>
                </Table>
            </div>
            {totalPages > 1 && (
                <Pagination
                    currentPage={currentPage}
                    totalPages={totalPages}
                    onPageChange={setCurrentPage}
                />
            )}
        </div>
    );
};

export default DynamicDataTable;

/**
 * @file ChangePassword.test.jsx
 * @description Unit tests for the ChangePassword component.
 * 
 * @tests
 * 1. Renders password change form with all inputs.
 * 2. Validates that new passwords match.
 * 3. Validates minimum password length.
 * 4. Validates that new password differs from current.
 * 5. Handles successful password change.
 * 6. Displays error on API failure.
 * 7. Shows success message after password change.
 */
import { render, screen, fireEvent, waitFor, cleanup } from '@testing-library/react';
import { describe, it, expect, vi, afterEach, beforeEach } from 'vitest';
import ChangePassword from './ChangePassword';
import React from 'react';
import apiClient from '../../api/apiClient';

// Mock the CSS module
vi.mock('./ChangePassword.module.css', () => ({
    default: {
        container: 'container',
        form: 'form',
        error: 'error',
        actions: 'actions',
        submitBtn: 'submitBtn',
        cancelBtn: 'cancelBtn',
        successMessage: 'successMessage',
        successIcon: 'successIcon'
    }
}));

// Mock apiClient
vi.mock('../../api/apiClient');

// Mock Button component
vi.mock('../ui/Button', () => ({
    Button: ({ children, intent, size, flat, grouped, ...props }) => (
        <button {...props}>{children}</button>
    )
}));

// Mock Input component
vi.mock('../ui/form/Input', () => ({
    Input: ({ label, id, name, helperText, error, icon, ...props }) => (
        <div>
            <label htmlFor={id || name}>{label}</label>
            <input id={id || name} name={name} {...props} />
        </div>
    )
}));

// Mock lucide-react icons
vi.mock('lucide-react', () => ({
    CheckCircle: () => <span>CheckIcon</span>
}));

describe('ChangePassword', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    afterEach(() => {
        cleanup();
        vi.useRealTimers();
    });

    const fillPasswordForm = (currentPassword, newPassword, confirmPassword) => {
        fireEvent.change(screen.getByLabelText(/current password/i), {
            target: { value: currentPassword }
        });
        fireEvent.change(screen.getByLabelText(/^new password$/i), {
            target: { value: newPassword }
        });
        fireEvent.change(screen.getByLabelText(/confirm new password/i), {
            target: { value: confirmPassword }
        });
    };

    it('renders password change form with all inputs', () => {
        render(<ChangePassword />);

        expect(screen.getByLabelText(/current password/i)).toBeInTheDocument();
        expect(screen.getByLabelText(/^new password$/i)).toBeInTheDocument();
        expect(screen.getByLabelText(/confirm new password/i)).toBeInTheDocument();
        expect(screen.getByRole('button', { name: /change password/i })).toBeInTheDocument();
    });

    it('validates that new passwords match', async () => {
        render(<ChangePassword />);

        fillPasswordForm('oldpass123', 'newpass123', 'differentpass');

        const submitButton = screen.getByRole('button', { name: /change password/i });
        fireEvent.click(submitButton);

        // Check if the error message is displayed
        expect(await screen.findByText(/^new passwords do not match$/i)).toBeInTheDocument();
        expect(apiClient).not.toHaveBeenCalled();
    });

    it('validates minimum password length', async () => {
        render(<ChangePassword />);

        fillPasswordForm('oldpass123', 'short', 'short');

        const submitButton = screen.getByRole('button', { name: /change password/i });
        fireEvent.click(submitButton);

        expect(await screen.findByText(/must be at least 6 characters/i)).toBeInTheDocument();
        expect(apiClient).not.toHaveBeenCalled();
    });

    it('validates that new password differs from current', async () => {
        render(<ChangePassword />);

        fillPasswordForm('samepass123', 'samepass123', 'samepass123');

        const submitButton = screen.getByRole('button', { name: /change password/i });
        fireEvent.click(submitButton);

        expect(await screen.findByText(/must be different from current password/i)).toBeInTheDocument();
        expect(apiClient).not.toHaveBeenCalled();
    });

    it('handles successful password change', async () => {
        vi.useFakeTimers();
        apiClient.mockResolvedValue({ success: true });
        const onSuccess = vi.fn();

        render(<ChangePassword onSuccess={onSuccess} />);

        fillPasswordForm('oldpass123', 'newpass123', 'newpass123');

        const submitButton = screen.getByRole('button', { name: /change password/i });
        fireEvent.click(submitButton);

        // Advance timers and microtasks
        await vi.runAllTimersAsync();

        expect(screen.getByText(/password changed successfully/i)).toBeInTheDocument();

        // Verify API was called correctly
        expect(apiClient).toHaveBeenCalledWith('/auth/change-password', {
            method: 'POST',
            body: {
                currentPassword: 'oldpass123',
                newPassword: 'newpass123'
            }
        });

        expect(onSuccess).toHaveBeenCalled();
    });

    it('displays error on API failure', async () => {
        apiClient.mockRejectedValueOnce({ message: 'Current password is incorrect' });

        render(<ChangePassword />);

        fillPasswordForm('wrongpass', 'newpass123', 'newpass123');

        const submitButton = screen.getByRole('button', { name: /change password/i });
        fireEvent.click(submitButton);

        expect(await screen.findByText(/current password is incorrect/i)).toBeInTheDocument();
    });

    it('shows success message after password change', async () => {
        apiClient.mockResolvedValueOnce({ success: true });

        render(<ChangePassword />);

        fillPasswordForm('oldpass123', 'newpass123', 'newpass123');

        const submitButton = screen.getByRole('button', { name: /change password/i });
        fireEvent.click(submitButton);

        expect(await screen.findByText(/password changed successfully/i)).toBeInTheDocument();
    });

    it('renders cancel button when onCancel is provided', () => {
        const onCancel = vi.fn();
        render(<ChangePassword onCancel={onCancel} />);

        const cancelButton = screen.getByRole('button', { name: /cancel/i });
        expect(cancelButton).toBeInTheDocument();

        fireEvent.click(cancelButton);
        expect(onCancel).toHaveBeenCalled();
    });

    it('clears error when user starts typing', async () => {
        render(<ChangePassword />);

        fillPasswordForm('oldpass123', 'short', 'short');

        const submitButton = screen.getByRole('button', { name: /change password/i });
        fireEvent.click(submitButton);

        expect(await screen.findByText(/must be at least 6 characters/i)).toBeInTheDocument();

        // Type in the current password field
        fireEvent.change(screen.getByLabelText(/current password/i), {
            target: { value: 'newvalue' }
        });

        expect(screen.queryByText(/must be at least 6 characters/i)).not.toBeInTheDocument();
    });
});

import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { User, Lock } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { Button } from '../ui/Button';
import { Input } from '../ui/form/Input';
import styles from './LoginForm.module.css';

const LoginForm = ({ onSuccess, onRegisterClick }) => {
    const { login } = useAuth();
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        try {
            if (username && password) {
                const res = await login(username, password);
                if (res.success) {
                    setUsername('');
                    setPassword('');
                    if (onSuccess) onSuccess();
                } else {
                    setError(res.message || 'Login failed');
                }
            }
        } catch (err) {
            setError('An unexpected error occurred');
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <form onSubmit={handleSubmit} className={styles.form}>
                {error && <p className={styles.error}>{error}</p>}
                <Input
                    id="username"
                    label="Username"
                    type="text"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    required
                    disabled={loading}
                    icon={User}
                />
                <Input
                    id="password"
                    label="Password"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    disabled={loading}
                    icon={Lock}
                />
                <Button type="submit" disabled={loading} className={styles.submitBtn}>
                    {loading ? 'Signing In...' : 'Sign In'}
                </Button>
            </form>
            <div className={styles.footer}>
                <p>
                    Don't have an account?
                    <Link to="/register" className={styles.link} onClick={onRegisterClick}>Register</Link>
                </p>
            </div>
        </>
    );
};

export default LoginForm;

import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import LoginForm from './LoginForm';
import { Button } from '../ui/Button';
import { Popover } from '../ui/Popover';
import { LayoutDashboard, User as UserIcon, LogOut } from 'lucide-react';
import styles from './LoginModal.module.css';

const LoginModal = () => {
    const { user, logout } = useAuth();
    const navigate = useNavigate();

    const closeModal = () => {
        document.getElementById('login-popover').hidePopover();
    };

    const handleLogout = async () => {
        navigate('/');
        await logout();
        closeModal();
    };

    const isLoggedIn = !!user;
    const currentUsername = user?.username;

    return (
        <Popover
            id="login-popover"
            className={styles.popover}
        >
            {isLoggedIn ? (
                <div className={styles.form}>
                    <h3>Hello, {currentUsername || 'User'}</h3>
                    {user?.role === 'admin' && (
                        <Link to="/admin" className={styles.profileLink} onClick={closeModal}>
                            <LayoutDashboard size={16} />
                            <span>Admin Dashboard</span>
                        </Link>
                    )}
                    <Link to="/profile" className={styles.profileLink} onClick={closeModal}>
                        <UserIcon size={16} />
                        <span>My Profile</span>
                    </Link>
                    <div className={`${styles.profileLink} ${styles.logoutLink}`} onClick={handleLogout}>
                        <LogOut size={16} />
                        <span>Logout</span>
                    </div>
                </div>
            ) : (
                <div className={styles.form}>
                    <h3>Login</h3>
                    <LoginForm onSuccess={closeModal} onRegisterClick={closeModal} />
                </div>
            )}
        </Popover>
    );
};

export default LoginModal;

import React, { useState, useEffect, useRef } from 'react';
import { Pencil, Library, Upload, Check } from 'lucide-react';
import apiClient from '../../api/apiClient';
import { useToast } from '../../context/ToastContext';
import styles from './ImageSelect.module.css';
import ImageUpload from './ImageUpload';

/**
 * ImageSelect: A premium popover component for selecting images from the library
 * or uploading new ones.
 * @param {string} value - Current selected image URL.
 * @param {function} onChange - Callback when an image is selected/changed.
 * @param {string} label - Label for the field.
 */
const ImageSelect = ({ value, onChange, label = "Select Image" }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [images, setImages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [tab, setTab] = useState('browse'); // 'browse' or 'upload'
    const popoverRef = useRef(null);
    const { addToast } = useToast();

    // Close on outside click
    useEffect(() => {
        const handleClickOutside = (e) => {
            if (popoverRef.current && !popoverRef.current.contains(e.target)) {
                setIsOpen(false);
            }
        };
        if (isOpen) document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isOpen]);

    const fetchImages = async () => {
        setLoading(true);
        try {
            const data = await apiClient('/upload');
            setImages(data);
        } catch (err) {
            addToast('Failed to load media library', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (isOpen && tab === 'browse') {
            fetchImages();
        }
    }, [isOpen, tab]);

    const handleSelect = (url) => {
        onChange(url);
        setIsOpen(false);
    };

    const handleUploadSuccess = (data) => {
        const uploaded = Array.isArray(data) ? data[0] : data;
        if (uploaded) {
            onChange(uploaded.url);
            setIsOpen(false);
            addToast('Image uploaded and selected', 'success');
        }
    };

    return (
        <div className={styles.container} ref={popoverRef}>
            <label className={styles.label}>{label}</label>

            <div className={styles.trigger} onClick={() => setIsOpen(!isOpen)}>
                {value ? (
                    <div className={styles.previewWrapper}>
                        <img src={`${value}?v=${Date.now()}`} alt="Selected" className={styles.selectedPreview} />
                        <div className={styles.changeOverlay}>
                            <Pencil size={18} />
                            <span>Change</span>
                        </div>
                    </div>
                ) : (
                    <div className={styles.placeholder}>
                        <span>Pick an Image</span>
                    </div>
                )}
            </div>

            {isOpen && (
                <div className={styles.popover}>
                    <div className={styles.popoverHeader}>
                        <div className={styles.tabs}>
                            <button
                                className={`${styles.tab} ${tab === 'browse' ? styles.activeTab : ''}`}
                                onClick={() => setTab('browse')}
                            >
                                <Library size={16} />
                                <span>Browse Library</span>
                            </button>
                            <button
                                className={`${styles.tab} ${tab === 'upload' ? styles.activeTab : ''}`}
                                onClick={() => setTab('upload')}
                            >
                                <Upload size={16} />
                                <span>Upload New</span>
                            </button>
                        </div>
                    </div>

                    <div className={styles.popoverContent}>
                        {tab === 'browse' ? (
                            <div className={styles.libraryGrid}>
                                {loading ? (
                                    <div className={styles.status}>Loading...</div>
                                ) : images.length === 0 ? (
                                    <div className={styles.status}>No images found</div>
                                ) : (
                                    images.map(img => (
                                        <div
                                            key={img._id}
                                            className={`${styles.imageCard} ${value === img.url ? styles.selectedCard : ''}`}
                                            onClick={() => handleSelect(img.url)}
                                            title={img.title || img.filename}
                                        >
                                            <img src={img.thumbnailUrl || img.url} alt={img.title} />
                                            {value === img.url && (
