import React, { createContext, useContext, useRef, useState, useCallback } from 'react';

export const DataContext = createContext(null);

/**
 * DataProvider: The central "Engine" for our Stale-While-Revalidate caching.
 * Uses a Map to store data by endpoint URL.
 * 
 * Provides:
 * - getCache(key): Retrieve data from cache.
 * - setCache(key, data): Store data in cache and update timestamp.
 * - invalidate(key?): Clear specific or all cache entries.
 * - cacheVersion: Incremented on every cache change to trigger re-renders in consumers.
 */
export const DataProvider = ({ children, initialData = {} }) => {
    // We use a ref for the cache to keep it stable and outside of the React render cycle
    // for immediate updates, but use state for "cache version" to trigger re-renders
    const cache = useRef(new Map());

    // Initialize cache with provided data (useful for Storybook/Testing)
    useState(() => {
        Object.entries(initialData).forEach(([key, data]) => {
            cache.current.set(key, { data, timestamp: Date.now() });
        });
    });

    const [cacheVersion, setCacheVersion] = useState(0);

    /**
     * setCache: Updates the internal ref and increments the version counter.
     */
    const setCache = useCallback((key, data) => {
        cache.current.set(key, {
            data,
            timestamp: Date.now(),
        });
        setCacheVersion(v => v + 1);
    }, []);

    /**
     * getCache: Retrieves an entry from the internal ref.
     */
    const getCache = useCallback((key) => {
        return cache.current.get(key);
    }, []);

    /**
     * invalidate: Clears a specific entry or the entire cache.
     */
    const invalidate = useCallback((key) => {
        if (key) {
            cache.current.delete(key);
        } else {
            cache.current.clear();
        }
        setCacheVersion(v => v + 1);
    }, []);

    const value = {
        getCache,
        setCache,
        invalidate,
        cacheVersion
    };

    return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
};

/**
 * useDataEngine: Access the low-level data cache and invalidation methods.
 */
export const useDataEngine = () => {
    const context = useContext(DataContext);
    if (!context) {
        throw new Error('useDataEngine must be used within a DataProvider');
    }
    return context;
};

import React, { createContext, useContext, useState, useCallback } from 'react';
import { ConfirmDialog } from '../components/ui/Modal/ConfirmDialog';
import { PromptDialog } from '../components/ui/Modal/PromptDialog';

export const ModalContext = createContext();

export const useModal = () => {
    const context = useContext(ModalContext);
    if (!context) throw new Error('useModal must be used within a ModalProvider');
    return context;
};

export const ModalProvider = ({ children }) => {
    const [modals, setModals] = useState([]);

    const confirm = useCallback((options) => {
        return new Promise((resolve) => {
            setModals((prev) => [
                ...prev,
                { id: Math.random().toString(36).substr(2, 9), type: 'confirm', options, resolve }
            ]);
        });
    }, []);

    const prompt = useCallback((options) => {
        return new Promise((resolve) => {
            setModals((prev) => [
                ...prev,
                { id: Math.random().toString(36).substr(2, 9), type: 'prompt', options, resolve }
            ]);
        });
    }, []);

    const closeModal = useCallback((id, result) => {
        setModals((prev) => {
            const modalIndex = prev.findIndex((m) => m.id === id);
            if (modalIndex !== -1) {
                const modal = prev[modalIndex];
                // Resolve the promise
                modal.resolve(result);
                // Remove this modal from the queue
                const newModals = [...prev];
                newModals.splice(modalIndex, 1);
                return newModals;
            }
            return prev;
        });
    }, []);

    const currentModal = modals[0] || null;

    return (
        <ModalContext.Provider value={{ confirm, prompt }}>
            {children}
            {currentModal && currentModal.type === 'confirm' && (
                <ConfirmDialog
                    key={currentModal.id}
                    {...currentModal.options}
                    onClose={(result) => closeModal(currentModal.id, result)}
                />
            )}
            {currentModal && currentModal.type === 'prompt' && (
                <PromptDialog
                    key={currentModal.id}
                    {...currentModal.options}
                    onClose={(result) => closeModal(currentModal.id, result)}
                />
            )}
        </ModalContext.Provider>
    );
};

