        e.preventDefault();
        setError('');
        setLoading(true);

        // Validation
        if (formData.password !== formData.confirmPassword) {
            setError('Passwords do not match');
            setLoading(false);
            return;
        }

        if (formData.password.length < 6) {
            setError('Password must be at least 6 characters');
            setLoading(false);
            return;
        }

        try {
            const { confirmPassword, ...registrationData } = formData;
            const response = await apiClient('/auth/register', {
                method: 'POST',
                body: registrationData
            });

            setSuccess(true);
            setFormData({
                username: '',
                name: '',
                email: '',
                password: '',
                confirmPassword: ''
            });
        } catch (err) {
            setError(err.message || 'Registration failed');
        } finally {
            setLoading(false);
        }
    };

    if (success) {
        return (
            <CenteredLayout>
                <Card className={styles.successCard}>
                    <CardBody>
                        <div className={styles.successIcon}>
                            <CheckCircle size={48} strokeWidth={2.5} />
                        </div>
                        <h1>Registration Successful!</h1>
                        <p>Your account has been created and is pending admin approval.</p>
                        <p>You will be able to log in once an administrator activates your account.</p>
                        <Button as={Link} to="/login" className={styles.loginLink}>
                            Return to Login
                        </Button>
                    </CardBody>
                </Card>
            </CenteredLayout>
        );
    }

    return (
        <CenteredLayout>
            <Card className={styles.registerCard}>
                <CardHeader>
                    <h1>Create Account</h1>
                    <p>Register for a new account</p>
                </CardHeader>

                <CardBody>
                    <form onSubmit={handleSubmit} className={styles.form}>
                        {error && <p className={styles.error}>{error}</p>}

                        <Input
                            id="username"
                            name="username"
                            label="Username *"
                            type="text"
                            value={formData.username}
                            onChange={handleChange}
                            required
                            disabled={loading}
                            icon={User}
                        />

                        <Input
                            id="name"
                            name="name"
                            label="Full Name *"
                            type="text"
                            value={formData.name}
                            onChange={handleChange}
                            required
                            disabled={loading}
                            icon={UserCircle}
                        />

                        <Input
                            id="email"
                            name="email"
                            label="Email *"
                            type="email"
                            value={formData.email}
                            onChange={handleChange}
                            required
                            disabled={loading}
                            icon={Mail}
                        />

                        <Input
                            id="password"
                            name="password"
                            label="Password *"
                            type="password"
                            value={formData.password}
                            onChange={handleChange}
                            required
                            disabled={loading}
                            minLength={6}
                            icon={Lock}
                        />

                        <Input
                            id="confirmPassword"
                            name="confirmPassword"
                            label="Confirm Password *"
                            type="password"
                            value={formData.confirmPassword}
                            onChange={handleChange}
                            required
                            disabled={loading}
                            minLength={6}
                            icon={Lock}
                        />

                        <Button type="submit" disabled={loading} className={styles.submitBtn}>
                            {loading ? 'Creating Account...' : 'Register'}
                        </Button>
                    </form>
                </CardBody>

                <CardFooter>
                    <p className={styles.footerText}>
                        Already have an account?{' '}
                        <Link to="/login" className={styles.link}>
                            Sign in
                        </Link>
                    </p>
                </CardFooter>
            </Card>
        </CenteredLayout>
    );
};

export default RegisterPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/form/Input';
import styles from './Setup.module.css';

const Setup = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    const { needsSetup, checkSetup, login } = useAuth();
    const navigate = useNavigate();

    useEffect(() => {
        // If setup not needed, go home
        if (!needsSetup) {
            navigate('/');
        }
    }, [needsSetup, navigate]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');

        if (password !== confirmPassword) {
            return setError('Passwords do not match');
        }

        setIsLoading(true);
        try {
            const res = await fetch('/api/auth/setup', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password }),
            });

            if (res.ok) {
                await checkSetup();
                const authRes = await login(username, password);
                if (authRes.success) {
                    navigate('/admin');
                }
            } else {
                const data = await res.json();
                setError(data.message || 'Setup failed');
            }
        } catch (err) {
            setError('Connection error');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className={styles.container}>
            <h1>Initial System Setup</h1>
            <p>Create the primary administrator account.</p>

            <form onSubmit={handleSubmit} className={styles.form}>
                <Input
                    label="Username"
                    type="text"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    required
                />

                <Input
                    label="Password"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                />

                <Input
                    label="Confirm Password"
                    type="password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    required
                />

                {error && <p className={styles.error}>{error}</p>}

                <Button type="submit" disabled={isLoading} className={styles.submitBtn}>
                    {isLoading ? 'Creating Admin...' : 'Finish Setup'}
                </Button>
            </form>
        </div>
    );
};

export default Setup;

import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import apiClient from '../api/apiClient';
import ChangePassword from '../components/auth/ChangePassword';
import { Button } from '../components/ui/Button';
import styles from './UserProfile.module.css';
import { User, ShieldCheck, Mail, LogOut, Loader2 } from 'lucide-react';
import { useState, useEffect } from 'react';

import { useNavigate } from 'react-router-dom';

/**
 * UserProfile: User profile page for managing personal information
 * Accessible to all logged-in users
 */
const UserProfile = () => {
    const { user, refreshUser, logout } = useAuth(); // Added logout from useAuth
    const { addToast } = useToast();
    const navigate = useNavigate();

    const [formData, setFormData] = useState({
        username: '',
        name: '',
        email: ''
    });
    const [loading, setLoading] = useState(false);
    const [isDirty, setIsDirty] = useState(false);

    useEffect(() => {
        if (user) {
            setFormData({
                username: user.username || '',
                name: user.name || '',
                email: user.email || ''
            });
        }
    }, [user]);

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
        setIsDirty(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            await apiClient('/auth/profile', {
                method: 'PUT',
                body: {
                    name: formData.name,
                    email: formData.email
                }
            });

            addToast('Profile updated successfully!', 'success');
            setIsDirty(false);
            refreshUser(); // Refresh user data in context
        } catch (err) {
            addToast(err.message || 'Failed to update profile', 'error');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordChangeSuccess = () => {
        addToast('Password changed successfully!', 'success');
    };

    const handleLogout = () => {
        navigate('/');
        logout();
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <h1>
                    <User size={32} />
                    <span>My Profile</span>
                </h1>
                <p>Manage your personal information and security settings</p>
            </div>

            <div className={styles.section}>
                <h2>
                    <User size={20} />
                    <span>Personal Information</span>
                </h2>
                <form onSubmit={handleSubmit} className={styles.form}>
                    <div className={styles.inputGroup}>
                        <label htmlFor="username">Username</label>
                        <input
                            id="username"
                            name="username"
                            type="text"
                            className={styles.input}
                            value={formData.username}
                            disabled
                            title="Username cannot be changed"
                        />
                        <span className={styles.hint}>Username cannot be changed</span>
                    </div>

                    <div className={styles.inputGroup}>
                        <label htmlFor="name">Full Name</label>
                        <input
                            id="name"
                            name="name"
                            type="text"
                            className={styles.input}
                            value={formData.name}
                            onChange={handleChange}
                            required
                            disabled={loading}
                        />
                    </div>

                    <div className={styles.inputGroup}>
                        <label htmlFor="email">Email Address</label>
                        <input
                            id="email"
                            name="email"
                            type="email"
                            className={styles.input}
                            value={formData.email}
                            onChange={handleChange}
                            required
                            disabled={loading}
                        />
                    </div>

                    <div className={styles.actions}>
                        <Button
                            type="submit"
                            className={styles.submitBtn}
                            disabled={!isDirty || loading}
                            intent="primary" // Added intent
                        >
                            {loading ? 'Saving...' : 'Save Changes'}
                        </Button>
                    </div>
                </form>
            </div>

            <div className={styles.separator}></div>

            <div className={styles.section}>
                <h2>
                    <ShieldCheck size={20} />
                    <span>Security</span>
                </h2>
                <ChangePassword onSuccess={handlePasswordChangeSuccess} />
            </div>
        </div>
    );
};

export default UserProfile;

