import React, { useState, useEffect } from 'react';
import { useDataTypes } from '../../hooks/useDynamicData';
import DynamicDataTable from '../../components/admin/DynamicDataTable';
import TabNavigation from '../../components/ui/TabNavigation';
import { Info } from 'lucide-react';
import styles from './AdminData.module.css';

/**
 * AdminData: Management page for dynamic data types.
 * Renders tabs for each data type and a DynamicDataTable for the active type.
 */
const AdminData = () => {
    const { data: types, loading, error } = useDataTypes();
    const [activeTypeId, setActiveTypeId] = useState(null);

    const [showGuide, setShowGuide] = useState(false);

    // Set first type as active by default once loaded
    useEffect(() => {
        if (types && types.length > 0 && !activeTypeId) {
            setActiveTypeId(types[0]._id);
        }
    }, [types, activeTypeId]);

    if (loading) return <div className={styles.loading}>Loading data configurations...</div>;
    if (error) return <div className={styles.error}>Error: {error.message}</div>;

    const activeType = types?.find(t => t._id === activeTypeId);

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <div className={styles.titleGroup}>
                    <h2>Data Management</h2>
                    <p>Manage content records across your application's data types.</p>
                </div>
                <button
                    className={styles.guideToggle}
                    onClick={() => setShowGuide(!showGuide)}
                >
                    <Info size={16} />
                    <span>{showGuide ? 'Hide Schema Guide' : 'Show Schema Guide'}</span>
                </button>
            </div>

            {showGuide && (
                <div className={styles.guide}>
                    <h3>Data Schema Configuration</h3>
                    <p>Each data type consists of fields defined by a common schema:</p>
                    <div className={styles.guideGrid}>
                        <div className={styles.guideItem}>
                            <strong>Name:</strong> The label displayed in the table header.
                        </div>
                        <div className={styles.guideItem}>
                            <strong>Type:</strong> The input method (text, number, boolean, date).
                        </div>
                        <div className={styles.guideItem}>
                            <strong>Required:</strong> Whether the field must be completed to save.
                        </div>
                        <div className={styles.guideItem}>
                            <strong>Default:</strong> The initial value assigned to new records.
                        </div>
                        <div className={styles.guideItem}>
                            <strong>Permissions:</strong> Controls for "canAdd", "canEdit", and "canDelete".
                        </div>
                    </div>

                    <p className={styles.guideNote}>
                        <em>* Reordering functionality is available for types flagged as "Ordered" in their configuration.</em>
                    </p>
                </div>
            )}

            {types && (
                <TabNavigation
                    tabs={types.map(t => ({ path: t._id, label: t.name }))}
                    variant="pill"
                    activeTab={activeTypeId}
                    onTabClick={setActiveTypeId}
                />
            )}

            <div className={styles.content}>
                {activeType ? (
                    <DynamicDataTable key={activeTypeId} type={activeType} />
                ) : (
                    <div className={styles.empty}>No data types defined.</div>
                )}
            </div>
        </div>
    );
};

export default AdminData;

import React, { useState, useEffect } from 'react';
import { Link as LinkIcon, Trash2, RefreshCw, Copy, Loader2 } from 'lucide-react';
import apiClient from '../../api/apiClient';
import { useToast } from '../../context/ToastContext';
import { useModal } from '../../context/ModalContext';
import styles from './AdminMedia.module.css';
import ImageUpload from '../../components/form/ImageUpload';
import { Button } from '../../components/ui/Button';

const AdminMedia = () => {
    const [images, setImages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [regenerating, setRegenerating] = useState(false);
    const [cacheBuster, setCacheBuster] = useState('');
    const { addToast } = useToast();
    const { confirm } = useModal();

    const fetchImages = async () => {
        setLoading(true);
        try {
            const data = await apiClient('/upload');
            setImages(data);
        } catch (err) {
            addToast('Failed to load images', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchImages();
    }, []);

    const handleDelete = async (id) => {
        const confirmed = await confirm({
            title: 'Delete Image',
            message: 'Are you sure you want to delete this image?',
            confirmText: 'Delete',
            intent: 'danger'
        });
        if (!confirmed) return;

        try {
            await apiClient(`/upload/${id}`, { method: 'DELETE' });
            addToast('Image deleted', 'success');
            setImages(prev => prev.filter(img => img._id !== id));
        } catch (err) {
            addToast('Failed to delete image', 'error');
        }
    };

    const copyToClipboard = (url) => {
        const fullUrl = window.location.origin + url;
        navigator.clipboard.writeText(fullUrl);
        addToast('URL copied to clipboard', 'success');
    };

    const handleTitleUpdate = async (id, newTitle) => {
        try {
            await apiClient(`/upload/${id}`, {
                method: 'PUT',
                body: { title: newTitle }
            });
            setImages(prev => prev.map(img =>
                img._id === id ? { ...img, title: newTitle } : img
            ));
        } catch (err) {
            addToast('Failed to update title', 'error');
        }
    };

    const handleUploadSuccess = (newImages) => {
        const imagesToAdd = Array.isArray(newImages) ? newImages : [newImages];
        addToast(`${imagesToAdd.length} image(s) uploaded successfully`, 'success');
        setImages(prev => [...imagesToAdd, ...prev]);
    };

    const handleRegenerate = async () => {
        const confirmed = await confirm({
            title: 'Regenerate Thumbnails',
            message: 'This will regenerate thumbnails for all images using the current config. Continue?',
            confirmText: 'Regenerate',
            intent: 'warning'
        });
        if (!confirmed) return;

        setRegenerating(true);
        try {
            const res = await apiClient('/upload/regenerate-thumbs', { method: 'POST' });
            addToast(`${res.message}: ${res.results.success} successes, ${res.results.failed} failed.`, 'success');

            // Set cache buster to force browser to reload images
            setCacheBuster(`?v=${Date.now()}`);
            fetchImages();
        } catch (err) {
            addToast('Regeneration failed', 'error');
        } finally {
            setRegenerating(false);
        }
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <div className={styles.titleInfo}>
                    <h2>Media Library</h2>
                    <Button
                        onClick={handleRegenerate}
                        disabled={regenerating || loading}
                        className={styles.regenerateBtn}
                        intent="secondary"
                        size="sm"
                    >
                        <RefreshCw size={14} className={regenerating ? styles.spin : ''} />
                        <span>{regenerating ? 'Regenerating...' : 'Regenerate Thumbnails'}</span>
                    </Button>
                </div>
                <div className={styles.uploader}>
                    <ImageUpload
                        onUpload={handleUploadSuccess}
                        label="Upload New Image(s)"
                        showPreview={false}
                        multiple={true}
                    />
                </div>
            </div>

            {loading ? (
                <div className={styles.loading}>
                    <Loader2 size={32} className={styles.spin} />
                    <span>Loading library...</span>
                </div>
            ) : (
                <div className={styles.grid}>
                    {images.length === 0 ? (
                        <p className={styles.empty}>No images found.</p>
                    ) : (
                        images.map(img => (
                            <div key={img._id} className={styles.card}>
                                <div className={styles.imageWrapper}>
                                    <img
                                        src={`${img.thumbnailUrl || img.url}${cacheBuster}`}
                                        alt={img.title || img.filename}
                                        loading="lazy"
                                    />
                                </div>
                                <div className={styles.actions}>
                                    <button
                                        onClick={() => copyToClipboard(img.url)}
                                        className={styles.copyBtn}
                                        title="Copy Full URL"
                                    >
                                        <Copy size={16} />
                                    </button>
                                    <button
                                        onClick={() => handleDelete(img._id)}
                                        className={styles.deleteBtn}
                                        title="Delete"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                                <div className={styles.titleArea}>
                                    <input
                                        type="text"
                                        defaultValue={img.title || img.filename}
                                        onBlur={(e) => handleTitleUpdate(img._id, e.target.value)}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter') {
                                                e.target.blur();
                                            }
                                        }}
                                        className={styles.titleInput}
                                        title="Click to edit title"
                                    />
                                    <div className={styles.originalName} title={img.originalName}>
                                        {img.originalName}
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            )}
        </div>
    );
};

export default AdminMedia;

import React, { useState, useEffect } from 'react';
import { useSiteMeta, useSiteMetaMutations } from '../../hooks/useSiteMeta';
import { useToast } from '../../context/ToastContext';
import { Settings, Plus, Trash2 } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import ImageSelect from '../../components/form/ImageSelect';
import styles from './AdminSettings.module.css';

const AdminSettings = () => {
    const { meta, loading: loadingMeta } = useSiteMeta();
    const { updateMeta, loading: saving } = useSiteMetaMutations();
    const { addToast } = useToast();

    const [formData, setFormData] = useState({
        title: '',
        description: '',
        logo: '',
        maintenanceMode: false,
        maintenanceMessage: '',
        footerText: '',
        footerLinks: []
    });
    const [isDirty, setIsDirty] = useState(false);

    // Sync form with loaded meta
    useEffect(() => {
        if (meta) {
            setFormData({
                title: meta.title || '',
                description: meta.description || '',
                logo: meta.logo || '',
                maintenanceMode: meta.maintenanceMode ?? false,
                maintenanceMessage: meta.maintenanceMessage || '',
                footerText: meta.footerText || '',
                footerLinks: meta.footerLinks || [],
            });
        }
    }, [meta]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
        setIsDirty(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const res = await updateMeta(formData);

        if (res.success) {
            setIsDirty(false);
            addToast('Settings saved successfully!', 'success');
        } else {
            addToast('Failed to save settings.', 'error');
        }
    };

    if (loadingMeta) return <div className={styles.container}>Loading settings...</div>;

    return (
        <div className={styles.container}>
            <h2 className={styles.title}>
                <Settings size={28} />
                <span>System Settings</span>
            </h2>

            <form onSubmit={handleSubmit} className={styles.form}>
                <div className={styles.field}>
                    <label className={styles.label} htmlFor="title">Application Title</label>
                    <input
                        id="title"
                        name="title"
                        type="text"
                        className={styles.input}
                        value={formData.title}
                        onChange={handleChange}
                        placeholder="Enter application name"
                        required
                    />
                </div>

                <div className={styles.field}>
                    <label className={styles.label} htmlFor="description">Description Tagline</label>
                    <textarea
                        id="description"
                        name="description"
                        className={styles.textarea}
                        value={formData.description}
                        onChange={handleChange}
                        placeholder="Say something about this project"
                    />
                </div>

                <div className={styles.field}>
                    <ImageSelect
                        label="Site Logo"
                        value={formData.logo}
                        onChange={(url) => {
                            setFormData(prev => ({ ...prev, logo: url }));
                            setIsDirty(true);
                        }}
                    />
                </div>

                <div className={styles.sectionDivider}>Footer Configuration</div>

                <div className={styles.field}>
                    <label className={styles.label} htmlFor="footerText">Footer Text</label>
                    <input
                        id="footerText"
                        name="footerText"
                        type="text"
                        className={styles.input}
                        value={formData.footerText}
                        onChange={handleChange}
                        placeholder="e.g. All rights reserved."
                    />
                </div>

                <div className={styles.field}>
                    <label className={styles.label}>Footer Links</label>
                    {formData.footerLinks.map((link, idx) => (
                        <div key={idx} style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.5rem' }}>
                            <input
                                type="text"
                                className={styles.input}
                                placeholder="Link Label"
                                value={link.label}
                                onChange={(e) => {
                                    const newLinks = [...formData.footerLinks];
                                    newLinks[idx].label = e.target.value;
                                    setFormData(prev => ({ ...prev, footerLinks: newLinks }));
                                    setIsDirty(true);
                                }}
                            />
                            <input
                                type="text"
                                className={styles.input}
                                placeholder="URL (e.g. /privacy)"
                                value={link.url}
                                onChange={(e) => {
                                    const newLinks = [...formData.footerLinks];
                                    newLinks[idx].url = e.target.value;
                                    setFormData(prev => ({ ...prev, footerLinks: newLinks }));
                                    setIsDirty(true);
                                }}
                            />
                            <Button
                                type="button"
                                intent="danger"
                                variant="outline"
                                size="sm"
                                onClick={() => {
                                    const newLinks = formData.footerLinks.filter((_, i) => i !== idx);
                                    setFormData(prev => ({ ...prev, footerLinks: newLinks }));
                                    setIsDirty(true);
                                }}
                                aria-label="Remove link"
                            >
                                <Trash2 size={16} />
                            </Button>
                        </div>
                    ))}
                    <Button
                        type="button"
                        intent="secondary"
                        variant="outline"
                        size="sm"
                        onClick={() => {
                            setFormData(prev => ({
                                ...prev,
                                footerLinks: [...prev.footerLinks, { label: '', url: '' }]
                            }));
                            setIsDirty(true);
                        }}
                        style={{ marginTop: '0.5rem', alignSelf: 'flex-start' }}
                    >
                        <Plus size={16} /> Add Link
                    </Button>
                </div>

                <div className={styles.sectionDivider}>Maintenance Mode</div>

                <div className={styles.field}>
                    <div className={styles.toggleRow}>
                        <label className={styles.label} htmlFor="maintenanceMode">Enable Maintenance Mode</label>
                        <input
                            id="maintenanceMode"
                            name="maintenanceMode"
                            type="checkbox"
                            className={styles.toggle}
                            checked={formData.maintenanceMode}
                            onChange={(e) => {
                                setFormData(prev => ({ ...prev, maintenanceMode: e.target.checked }));
                                setIsDirty(true);
                            }}
                        />
                    </div>
                    <p className={styles.hint}>When enabled, non-admin users will be redirected to a maintenance landing page.</p>
                </div>

                <div className={styles.field}>
                    <label className={styles.label} htmlFor="maintenanceMessage">Maintenance Message</label>
                    <textarea
                        id="maintenanceMessage"
                        name="maintenanceMessage"
                        className={styles.textarea}
                        value={formData.maintenanceMessage}
                        onChange={handleChange}
                        placeholder="Customize the message shown to users"
                        disabled={!formData.maintenanceMode}
                    />
                </div>

                <div className={styles.actions}>
                    <button
                        type="submit"
                        className={styles.saveBtn}
                        disabled={!isDirty || saving}
                    >
                        {saving ? 'Saving...' : 'Save Changes'}
                    </button>
                </div>
            </form>
        </div>
    );
};

export default AdminSettings;

import React from 'react';
import { MemoryRouter } from 'react-router-dom';
import { AuthContext, AuthProvider } from '../context/AuthContext';
import { DataContext, DataProvider } from '../context/DataContext';
import { ToastContext, ToastProvider } from '../context/ToastContext';
import { ModalProvider } from '../context/ModalContext';

/**
 * MockAppDecorator: A Storybook decorator that provides all necessary 
 * application contexts with mocked data/state.
 */
export const withAppProviders = (Story, context) => {
    // Extraction of custom story parameters for mocking
    const { 
        user = null, 
        meta = { title: 'Storybook CMS', logo: null },
        initialData = {}
    } = context.parameters?.mockData || {};

    // Combine site meta into initialData for DataProvider
    const fullInitialData = {
        '/site/meta': meta,
        ...initialData
    };

    // Global fetch mock for Storybook
    React.useEffect(() => {
        const originalFetch = window.fetch;
        window.fetch = async (url, options) => {
            const endpoint = url.replace('/api', '');

            // Handle GET requests using initialData
            if (!options?.method || options.method === 'GET') {
                const data = fullInitialData[endpoint];
                if (data) {
                    return {
                        ok: true,
                        json: async () => data,
                        headers: { get: () => 'application/json' }
                    };
                }
            }

            // Handle mutations (POST, PUT, DELETE) - always succeed in mock
            return {
                ok: true,
                json: async () => ({ success: true, results: [{ url: 'https://placehold.co/100', filename: 'mock.png' }] }),
                headers: { get: () => 'application/json' }
            };
        };

        return () => {
            window.fetch = originalFetch;
        };
    }, [fullInitialData]);

    return (
        <DataProvider initialData={fullInitialData}>
            <ToastProvider>
                <ModalProvider>
                    <MemoryRouter>
                        <MockAuthProvider user={user}>
                            <div className="storybook-wrapper">
                                <Story />
                            </div>
                        </MockAuthProvider>
                    </MemoryRouter>
                </ModalProvider>
            </ToastProvider>
        </DataProvider>
    );
};

// Internal simplified AuthProvider for Storybook mocking
const MockAuthProvider = ({ children, user }) => {
    const value = {
        user,
        loading: false,
        needsSetup: false,
        login: async () => ({ success: true }),
        logout: async () => console.log('Mock Logout'),
        checkAuth: async () => {},
        refreshUser: async () => {},
        checkSetup: async () => {}
    };

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
};
